//! Opt-in native qualification bridge. No live installer entry or source discovery.
//! Sources must be generated by the admitted official Electron process, which
//! must have retired before this exact child starts. The enrolled receiver owns
//! all inherited handles and keeps its genuine private Secret Service alive.
#[cfg(test)]
use super::{PreparedSessions, SelectedSource, import, source};
#[cfg(test)]
use browser_continuity::sessions::{SameSite, Service};
use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::{
    fs::{File, OpenOptions},
    io::Read,
    os::{
        fd::FromRawFd,
        unix::fs::{FileExt, MetadataExt, OpenOptionsExt},
    },
    path::Path,
};
#[cfg(test)]
use std::{io::Write, path::PathBuf, sync::Arc};
#[cfg(test)]
use zeroize::Zeroizing;

const MARKER: &str = "/run/tilo-official-session-source-qualification";
#[cfg(test)]
const SLACK_FD: i32 = 83;
#[cfg(test)]
const DISCORD_FD: i32 = 84;
#[cfg(test)]
const ACCOUNTS_FD: i32 = 86;
#[cfg(test)]
const REPORT_FD: i32 = 87;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Guard {
    schema: u32,
    receiver_sha256: String,
    bridge_sha256: String,
}
fn digest_shape(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}
fn executable_digest(path: &Path) -> String {
    // /proc/<exact-owned-parent>/exe is a kernel link, intentionally followed.
    // The open descriptor, immutable ownership and before/after facts are proof.
    let file = File::open(path).expect("qualification executable unavailable");
    held_executable_digest(&file)
}
pub fn held_executable_digest(file: &File) -> String {
    let before = file
        .metadata()
        .expect("qualification executable facts unavailable");
    assert!(before.is_file() && before.uid() == 0 && before.mode() & 0o022 == 0);
    assert!(before.len() > 0 && before.len() <= 512 * 1024 * 1024);
    let mut hash = Sha256::new();
    let mut buffer = [0; 65536];
    let mut bytes = 0u64;
    loop {
        let count = file
            .read_at(&mut buffer, bytes)
            .expect("qualification executable read refused");
        if count == 0 {
            break;
        }
        bytes = bytes
            .checked_add(count as u64)
            .expect("qualification executable overflow");
        assert!(bytes <= before.len());
        hash.update(&buffer[..count]);
    }
    let after = file
        .metadata()
        .expect("qualification executable facts unavailable");
    assert!(bytes == before.len() && stamp(&before) == stamp(&after));
    hex::encode(hash.finalize())
}
fn stamp(facts: &std::fs::Metadata) -> (u64, u64, u64, i64, i64, i64, i64) {
    (
        facts.dev(),
        facts.ino(),
        facts.len(),
        facts.mtime(),
        facts.mtime_nsec(),
        facts.ctime(),
        facts.ctime_nsec(),
    )
}
pub fn guarded_owner() -> u32 {
    let owner = rustix::process::getuid().as_raw();
    assert!(owner == 99 && owner == rustix::process::geteuid().as_raw());
    assert!(unsafe { libc::getgid() } == 99 && unsafe { libc::getegid() } == 99);
    assert!(unsafe { libc::getgroups(0, std::ptr::null_mut()) } == 0);
    assert!(
        unsafe { libc::getppid() } == 1,
        "requires exact owned receiving namespace init"
    );
    let mut marker = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
        .open(MARKER)
        .expect("explicit root-admitted source qualification required");
    let facts = marker
        .metadata()
        .expect("qualification guard facts unavailable");
    assert!(
        facts.is_file() && facts.uid() == 0 && facts.nlink() == 1 && facts.mode() & 0o777 == 0o444
    );
    assert!(facts.len() > 0 && facts.len() <= 1024);
    let mut bytes = Vec::new();
    Read::by_ref(&mut marker)
        .take(1025)
        .read_to_end(&mut bytes)
        .expect("qualification guard read refused");
    assert!(bytes.len() <= 1024 && stamp(&facts) == stamp(&marker.metadata().unwrap()));
    let guard: Guard = serde_json::from_slice(&bytes).expect("qualification guard malformed");
    assert!(
        guard.schema == 1
            && digest_shape(&guard.receiver_sha256)
            && digest_shape(&guard.bridge_sha256)
    );
    assert!(
        unsafe { libc::fcntl(88, libc::F_GETFD) } >= 0
            && unsafe { libc::fcntl(89, libc::F_GETFD) } >= 0
    );
    let receiver = unsafe { File::from_raw_fd(88) };
    let namespace = unsafe { File::from_raw_fd(89) };
    assert!(unsafe { libc::fcntl(88, libc::F_SETFD, libc::FD_CLOEXEC) } == 0);
    assert!(unsafe { libc::fcntl(89, libc::F_SETFD, libc::FD_CLOEXEC) } == 0);
    assert!(guard.receiver_sha256 == held_executable_digest(&receiver));
    let actual_namespace = File::open("/proc/self/ns/pid").unwrap().metadata().unwrap();
    let held_namespace = namespace.metadata().unwrap();
    assert!(
        (actual_namespace.dev(), actual_namespace.ino())
            == (held_namespace.dev(), held_namespace.ino())
    );
    assert!(unsafe { libc::ioctl(89, 0xb703) } == libc::CLONE_NEWPID);
    assert!(guard.bridge_sha256 == executable_digest(Path::new("/proc/self/exe")));
    owner
}
pub fn held_directory(slot: i32, path: &Path, owner: u32) -> File {
    // The dedicated qualification child owns these inherited slots exactly once.
    assert!(
        unsafe { libc::fcntl(slot, libc::F_GETFD) } >= 0,
        "qualification handle absent"
    );
    let file = unsafe { File::from_raw_fd(slot) };
    assert!(unsafe { libc::fcntl(slot, libc::F_SETFD, libc::FD_CLOEXEC) } == 0);
    let held = file
        .metadata()
        .expect("qualification handle facts unavailable");
    assert!(held.is_dir() && held.uid() == owner && held.mode() & 0o777 == 0o700);
    let named = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW | libc::O_DIRECTORY | libc::O_NONBLOCK)
        .open(path)
        .expect("fixed qualification directory absent");
    let named = named.metadata().unwrap();
    assert!(named.is_dir() && named.uid() == owner && named.mode() & 0o777 == 0o700);
    assert!((held.dev(), held.ino()) == (named.dev(), named.ino()));
    file
}
#[cfg(test)]
fn assert_material(session: &browser_continuity::sessions::SessionCookies, service: Service) {
    assert!(session.service == service && session.source_snapshot_digest != [0; 32]);
    match service {
        Service::Slack => {
            assert!(
                session.schema == 1
                    && session.cookies.len() == 1
                    && session.origin_storage.is_empty()
            );
            let cookie = &session.cookies[0];
            assert!(
                cookie.host == "app.slack.com"
                    && cookie.domain == "app.slack.com"
                    && cookie.host_only
            );
            assert!(
                cookie.name == "__Host-tilo-source-fixture"
                    && cookie.value == "synthetic-electron-source-cookie"
            );
            assert!(
                cookie.path == "/"
                    && cookie.secure
                    && cookie.http_only
                    && cookie.same_site == SameSite::Lax
            );
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs() as i64;
            assert!(
                cookie
                    .expires_unix_seconds
                    .is_some_and(|expiry| expiry > now + 23 * 3600 && expiry <= now + 86401)
            );
        }
        Service::Discord => {
            assert!(
                session.schema == 2
                    && session.cookies.is_empty()
                    && session.origin_storage.len() == 1
            );
            let entry = &session.origin_storage[0];
            assert!(entry.origin == "https://discord.com" && entry.key == "token");
            assert!(
                entry.value == "\"synthetic-electron-source-token\""
                    && entry.source_snapshot_digest != [0; 32]
            );
        }
    }
}

#[test]
fn official_electron_source_seals_and_imports_enrolled_receiver_custody() {
    let owner = guarded_owner();
    let home = PathBuf::from(std::env::var_os("HOME").expect("qualification HOME absent"));
    assert!(home.is_absolute() && home.file_name() == Some(std::ffi::OsStr::new("home")));
    let fixture = home.parent().expect("canonical fixture parent absent");
    assert!(fixture.parent() == Some(Path::new("/var/tmp")));
    assert!(
        fixture
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(|name| name.starts_with("tilo-receiver-"))
    );
    let parent = std::fs::symlink_metadata(fixture).expect("fixture custody unavailable");
    assert!(
        parent.is_dir()
            && parent.uid() == 0
            && parent.gid() == owner
            && parent.mode() & 0o7777 == 0o750
    );
    assert!(
        std::env::var_os("XDG_CONFIG_HOME").as_deref() == Some(fixture.join("config").as_os_str())
    );
    let target = accounts::config_root().expect("private enrolled receiver root absent");
    assert!(target == fixture.join("config/tilo"));
    let slack = held_directory(SLACK_FD, &home.join("source-format/slack"), owner);
    let discord = held_directory(DISCORD_FD, &home.join("source-format/discord"), owner);
    let destination = held_directory(ACCOUNTS_FD, &target, owner);
    let mut identity = [0; 32];
    // Only the exact enrolled namespace init sends this public key. Bound input
    // and EOF prevent a second request or accidental secret-bearing payload.
    let mut input = std::io::stdin().lock();
    input
        .read_exact(&mut identity)
        .expect("enrolled public key absent");
    let mut extra = [0];
    assert!(input.read(&mut extra).unwrap() == 0 && identity != [0; 32]);
    assert!(
        accounts::AccountStore::load_in(&target).is_empty(),
        "receiving account store must be fresh"
    );
    let application = source::slack_linux::SlackApplication::at(Path::new("/fixture/slack"))
        .expect("exact pinned public Slack application required");
    let grant = source::SourceGrant::new(slack, browser_continuity::Provider::Chromium)
        .expect("held selected Slack source refused");
    assert!(
        source::verify_official_fixture_store(&grant)
            .expect("actual encrypted schema24 store required")
    );
    let adapter = source::slack_linux::SlackLinux::for_grant(&grant, application)
        .expect("selected original-owner Slack decryptor refused");
    let grant = grant
        .with_chromium_decryptor(Arc::new(adapter))
        .expect("Slack binding refused");
    let discord = source::discord_origin::DiscordOriginGrant::new(discord)
        .expect("selected Discord source refused");
    let binding = format!("official-format-qualification:{}", uuid::Uuid::new_v4());
    let prepared = PreparedSessions::capture_selected(
        identity,
        binding.clone(),
        vec![
            SelectedSource::Cookies(grant, Service::Slack),
            SelectedSource::DiscordOrigin(discord),
        ],
    )
    .expect("official-format production extraction refused");
    let mut password = Zeroizing::new([0; 32]);
    tilo_seal::fill_random(&mut password[..]).expect("private sealing randomness unavailable");
    let (sealed, declaration) = prepared
        .seal(&password[..])
        .expect("canonical session sealing refused");
    assert!(declaration.consumer_protocol == 2 && declaration.sessions.len() == 2);
    // Authentication of a foreign enrolled key must refuse before account writes.
    let mut foreign = identity;
    foreign[0] ^= 1;
    assert!(
        import(
            &sealed,
            &declaration,
            &password[..],
            foreign,
            &binding,
            &target
        )
        .is_err()
    );
    assert!(accounts::AccountStore::load_in(&target).is_empty());
    import(
        &sealed,
        &declaration,
        &password[..],
        identity,
        &binding,
        &target,
    )
    .expect("canonical enrolled receiver account import refused");
    let store = accounts::AccountStore::load_in(&target);
    assert!(store.len() == 2);
    let custodian = account_custody::Custodian::for_root(Some(target.clone()));
    for selected in &declaration.sessions {
        let session = custodian
            .service_session(
                &accounts::AccountId::from(selected.id.clone()),
                identity,
                &binding,
            )
            .expect("actual readonly selected-session custody refused");
        assert_material(&session, selected.service);
    }
    let final_named = File::open(&target).unwrap().metadata().unwrap();
    let held = destination.metadata().unwrap();
    assert!((held.dev(), held.ino()) == (final_named.dev(), final_named.ino()));
    assert!(
        unsafe { libc::fcntl(REPORT_FD, libc::F_GETFD) } >= 0,
        "qualification report handle absent"
    );
    let mut report = unsafe { File::from_raw_fd(REPORT_FD) };
    let public = serde_json::json!({"schema":1,"consumer_protocol":2,"source_format":"electron-44.4.5", "sealed_custody_verified":true,"authenticated":false,"sessions":declaration.sessions});
    let encoded = serde_json::to_vec(&public).unwrap();
    assert!(encoded.len() <= 1024);
    report
        .write_all(&encoded)
        .expect("public qualification report refused");
    report
        .flush()
        .expect("public qualification report flush refused");
}
